def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def ranges(n, separators):
        out, start = [], 0
        for s in separators:
            if start < s:
                out.append((start, s))
            start = s + 1
        if start < n:
            out.append((start, n))
        return out

    rows = ranges(h, sep_rows)
    cols = ranges(w, sep_cols)
    blocks = [(r0, r1, c0, c1) for r0, r1 in rows for c0, c1 in cols]

    def count(block):
        r0, r1, c0, c1 = block
        return sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))

    source = max(blocks, key=count)
    r0, r1, c0, c1 = source
    pattern = [(r-r0, c-c0, grid[r][c])
               for r in range(r0, r1) for c in range(c0, c1)
               if grid[r][c] != bg]

    result = [row[:] for row in grid]
    for br0, br1, bc0, bc1 in blocks:
        for dr, dc, color in pattern:
            if br0 + dr < br1 and bc0 + dc < bc1:
                result[br0 + dr][bc0 + dc] = color
    return result
